function dataDiskLetterFree(params) {
  // Hides a drive letter in a row of the Data Disks table when another row
  // already uses it, so two disks cannot ask for the same letter.
  // params: the table's rows, the letter offered, this row's own letter.
  var rows = params[0] || [];
  var letter = params[1];
  if (!letter || letter === params[2]) return true;
  for (var i = 0; i < rows.length; i++) {
    if (rows[i] && rows[i].drive_letter === letter) return false;
  }
  return true;
}
